/* Записки с кодами и подсказками. */
LAB.codeNote = function (code, room, n) {
  var v = [
    { t: "Код двери: " + room, x: "Напоминание самому себе: код от двери в помещение «" + room + "» — " + code + ". Записку сжечь после прочтения. Не сжёг." },
    { t: "Стикер на мониторе: код двери «" + room + "»", x: room + ": " + code + ". Сменить код после проверки. Не сменил." },
    { t: "Сообщение коменданта: код двери «" + room + "»", x: "Временный код двери «" + room + "» — " + code + ". Сообщите охране, если код утёк. Охране сообщать некому." },
    { t: "Записка на ладони: код двери «" + room + "»", x: "На обрывке бумаги, видимо, переписано с руки: «" + room + " — " + code + "»." }
  ];
  return v[(n || 0) % v.length];
};
LAB.safeNote = function (code, room, n) {
  code = String(code).split("").join(" "); /* по цифрам: «четыре восемь два один» */
  var v = [
    { t: "Код сейфа в помещении «" + room + "»", x: "Сейф в помещении «" + room + "»: " + code + ". Если меня нет — забирайте всё." },
    { t: "Бухгалтерия: код сейфа в «" + room + "»", x: "Наличные кредиты — в сейфе, помещение «" + room + "». Комбинация: " + code + "." }
  ];
  return v[(n || 0) % v.length];
};
/* (3.0) Пароль от запертого компьютера. */
LAB.pinNote = function (code, room, n) {
  code = String(code).split("").join(" ");
  var v = [
    { t: "Пароль компьютера в «" + room + "»", x: "Компьютер в помещении «" + room + "»: пароль " + code + ". Не забыть, не потерять, никому не показывать." },
    { t: "Стикер: пароль от компьютера", x: "Напоминание: вход в компьютер, помещение «" + room + "», — " + code + ". Отдел безопасности требует менять пароль раз в месяц. Не менял." },
    { t: "Пароль в «" + room + "»", x: "Если меня нет на месте — мой компьютер в «" + room + "», пароль " + code + ". Почту проверьте сами." }
  ];
  return v[(n || 0) % v.length];
};
LAB.secretNote = function (room, side, n) {
  /* стороны — как в игре: впереди, сзади, слева, справа */
  var sw = { N: "передней", S: "задней", E: "правой", W: "левой" }[side] || "дальней";
  var v = [
    { t: "Сквозняк", x: "В помещении «" + room + "» тянет холодом от " + sw + " стены. За панелью что-то есть. Подойдите вплотную и прислушайтесь." },
    { t: "Схема с пометкой", x: "На схеме этажа рядом с помещением «" + room + "» от руки дорисована комната, которой нет на плане. Стрелка у " + sw + " стены. Приписка: «Из неё есть второй выход — в соседний коридор»." }
  ];
  return v[(n || 0) % v.length];
};
/* Записка с отгадкой голосового замка. */
LAB.riddleNote = function (rd, room, n) {
  var v = [
    { t: "Отгадка на замок «" + room + "»", x: "Голосовой замок помещения «" + room + "» опять спрашивает загадку. Чтобы не мучиться: «" + rd.q + "» — ответ «" + rd.a[0] + "». Не благодарите." },
    { t: "Шпаргалка охранника: замок «" + room + "»", x: "Замок «" + room + "». Вопрос про то, что «" + rd.hint.replace(/[.!]$/, "").toLowerCase() + "». Ответ — «" + rd.a[0] + "». Записку съесть." }
  ];
  return v[(n || 0) % v.length];
};

